import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Remove near-duplicates based on correlation
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, i], feats.x[:, j])[0,1]) >= 0.6:
                correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Build set of unique features (keep one from each correlated pair)
    unique_features = set(feats.ids)
    for fid1, fid2 in correlated_pairs:
        if fid2 in unique_features:
            unique_features.remove(fid2)

    # Filter to unique features
    unique_ids = tuple(sorted(unique_features))

    # Calculate effect sizes and p-values for each feature
    effects = []
    for i, fid in enumerate(unique_ids):
        col_idx = feats.column(fid)
        x_col = feats.x[:, col_idx]
        y = feats.y
        mean_y1 = np.mean(x_col[y == 1])
        mean_y0 = np.mean(x_col[y == 0])
        effect_size = mean_y1 - mean_y0

        # Welch's t-test
        group0 = x_col[y == 0]
        group1 = x_col[y == 1]
        if len(group0) > 1 and len(group1) > 1:
            t_stat, p_val = stats.ttest_ind(group0, group1, equal_var=False)
        else:
            p_val = 1.0

        effects.append((fid, effect_size, p_val))

    # Sort by effect size (absolute value) then p-value
    effects.sort(key=lambda x: (-abs(x[1]), x[2]))

    # Select top candidates for drivers (at most MAX_DRIVERS)
    drivers = []
    for fid, _, _ in effects[:MAX_DRIVERS]:
        if fid in unique_features:
            drivers.append(fid)

    # If no strong drivers, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build logistic regression features
    columns = tuple(drivers)
    products = []

    # Add interaction terms for pairs of drivers
    for i, d1 in enumerate(drivers):
        for d2 in drivers[i+1:]:
            products.append((d1, d2))

    # Simple weighted score using effect sizes
    loadings = {}
    for fid, effect, _ in effects:
        if fid in unique_features and fid in drivers:
            loadings[fid] = effect

    # Ensure we don't exceed MAX_DRIVERS in drivers
    if len(drivers) > MAX_DRIVERS:
        drivers = drivers[:MAX_DRIVERS]

    return Design(drivers=tuple(drivers), columns=columns, products=tuple(products), loadings=loadings)
